#!/usr/bin/env python3
import sys, os, gzip, getopt, random, re, math
from collections import defaultdict

VERSION = "1.5-r133"

def err(msg):
    sys.stderr.write(msg)
def out(msg):
    sys.stdout.write(msg)

# helpers for file opening
def open_input(path):
    if path is None or path == "-":
        return sys.stdin.buffer
    if path.endswith(".gz"):
        try:
            return gzip.open(path, 'rb')
        except:
            return open(path, 'rb')
    # try detect gzip magic
    try:
        with open(path, 'rb') as f:
            magic = f.read(2)
            if magic == b'\x1f\x8b':
                return gzip.open(path, 'rb')
    except:
        pass
    return open(path, 'rb')

def parse_fastx(handle):
    # handle is binary file
    data = handle.read()
    if not data:
        return []
    # decode
    text = data.decode('utf-8', errors='ignore')
    lines = text.splitlines()
    records = []
    i=0
    # skip empty
    while i < len(lines) and lines[i].strip() == "":
        i+=1
    if i >= len(lines):
        return records
    first = lines[i].strip()
    is_fastq = first.startswith('@')
    is_fasta = first.startswith('>')
    if is_fastq:
        # parse as FASTQ 4 lines per record, but allow wrapped?
        # We'll parse strictly 4 lines per record
        while i < len(lines):
            if lines[i].strip() == "":
                i+=1; continue
            h = lines[i].strip()
            if not h.startswith('@'):
                # maybe fasta inside fastq file? treat as fasta
                break
            header = h[1:]
            name = header.split()[0] if header else ""
            comment = header[len(name):].lstrip() if header else ""
            i+=1
            if i >= len(lines): break
            seq = lines[i].strip()
            i+=1
            if i >= len(lines): break
            plus = lines[i].strip()
            # plus line should start with '+'
            i+=1
            if i >= len(lines): break
            qual = lines[i].strip()
            i+=1
            # handle wrapped qual/seq? if qual length < seq length, continue reading
            # For seqtk, qual may be wrapped similar to seq, but we handle by reading until length matches or next header
            while len(qual) < len(seq) and i < len(lines) and not lines[i].startswith('@') and not lines[i].startswith('>'):
                qual += lines[i].strip()
                i+=1
            records.append((name, comment, seq, qual, True))
    else:
        # FASTA
        name = None
        comment = ""
        seq_parts = []
        while i < len(lines):
            line = lines[i].strip()
            i+=1
            if line == "":
                continue
            if line.startswith('>'):
                if name is not None:
                    records.append((name, comment, ''.join(seq_parts), None, False))
                header = line[1:]
                name = header.split()[0] if header else ""
                comment = header[len(name):].lstrip() if header else ""
                seq_parts = []
            elif line.startswith('@') and False:
                # unlikely
                pass
            else:
                seq_parts.append(line.strip())
        if name is not None:
            records.append((name, comment, ''.join(seq_parts), None, False))
    return records

def read_fastx_path(path):
    # return records
    if path is None or path == "-":
        # read from stdin buffer
        data = sys.stdin.buffer.read()
        if not data:
            return []
        text = data.decode('utf-8', errors='ignore')
        # reuse parsing
        import io
        handle = io.BytesIO(data)
        return parse_fastx(handle)
    else:
        try:
            # try gzip
            if path.endswith('.gz'):
                with gzip.open(path, 'rt') as f:
                    txt = f.read()
                    import io
                    return parse_fastx(io.BytesIO(txt.encode()))
            else:
                # detect gzip magic
                with open(path, 'rb') as fb:
                    magic = fb.read(2)
                    fb.seek(0)
                    if magic == b'\x1f\x8b':
                        with gzip.open(path, 'rt') as f:
                            txt = f.read()
                            import io
                            return parse_fastx(io.BytesIO(txt.encode()))
                    else:
                        with open(path, 'r') as f:
                            txt = f.read()
                            import io
                            return parse_fastx(io.BytesIO(txt.encode()))
        except FileNotFoundError:
            return None
        except Exception as e:
            # try binary
            try:
                with open(path, 'rb') as fb:
                    return parse_fastx(fb)
            except:
                return None

def write_fastx(records, line_len=0, is_fastq=False):
    out_lines = []
    for name, comment, seq, qual, orig_is_fastq in records:
        header = name
        if comment:
            header = f"{name} {comment}"
        # line wrapping
        if line_len > 0:
            # wrap seq
            seq_wrapped = '\n'.join(seq[i:i+line_len] for i in range(0, len(seq), line_len))
            if is_fastq and qual is not None:
                qual_wrapped = '\n'.join(qual[i:i+line_len] for i in range(0, len(qual), line_len))
            else:
                qual_wrapped = qual
        else:
            seq_wrapped = seq
            qual_wrapped = qual
        if is_fastq:
            out_lines.append(f"@{header}\n{seq_wrapped}\n+\n{qual_wrapped}\n")
        else:
            out_lines.append(f">{header}\n{seq_wrapped}\n")
    sys.stdout.write(''.join(out_lines))

# command implementations

def cmd_size(args):
    # size has no options; takes <in.fa>
    # if args empty, read stdin
    # if args has one file, read that
    # if file not found, error
    if len(args) == 0:
        records = parse_fastx(sys.stdin.buffer)
        n = len(records)
        b = sum(len(seq) for _,_,seq,_,_ in records)
        sys.stdout.write(f"{n}\t{b}\n")
        return 0
    elif len(args) == 1:
        path = args[0]
        recs = read_fastx_path(path)
        if recs is None:
            sys.stderr.write(f"[E::stk_size] failed to open the input file/stream.\n")
            return 1
        n = len(recs)
        b = sum(len(seq) for _,_,seq,_,_ in recs)
        sys.stdout.write(f"{n}\t{b}\n")
        return 0
    else:
        # too many args, treat first as file, ignore?
        path = args[0]
        recs = read_fastx_path(path)
        if recs is None:
            sys.stderr.write(f"[E::stk_size] failed to open the input file/stream.\n")
            return 1
        n = len(recs)
        b = sum(len(seq) for _,_,seq,_,_ in recs)
        sys.stdout.write(f"{n}\t{b}\n")
        return 0

def cmd_comp(args):
    # comp: get nucleotide composition
    # options: -u (count only uppercase), -r <file> (reference?) but not needed
    # We'll implement simple
    # getopt handling for -u and -r
    try:
        opts, rest = getopt.getopt(args, "ur:")
    except getopt.GetoptError as e:
        # e.msg like "option -h not recognized"
        # translate to "comp: invalid option -- 'h'"
        opt = str(e).split()[-1] if str(e) else ""
        # e.opt is the option char
        bad = e.opt if hasattr(e, 'opt') else opt.strip("'")
        # try extract
        if bad and len(bad)==2 and bad[0]=='-':
            bad = bad[1]
        sys.stderr.write(f"comp: invalid option -- '{bad}'\n")
        return 1
    # handle -r requires arg, getopt will error
    count_upper_only = False
    ref_path = None
    for o,a in opts:
        if o == '-u':
            count_upper_only = True
        elif o == '-r':
            ref_path = a
    # need at least one file or stdin
    if len(rest) == 0:
        # read stdin
        recs = parse_fastx(sys.stdin.buffer)
        if not recs:
            return 0
    else:
        path = rest[0]
        recs = read_fastx_path(path)
        if recs is None:
            sys.stderr.write(f"[E::stk_comp] failed to open the input file/stream.\n")
            return 1
        if not recs:
            return 0
    # for each record output comp line
    # columns: name, len, A, C, G, T, het2, het3, N, CpG*2, tv, ts, CpG_ts ?
    # We'll compute
    # define sets
    transversions = set(['S','W','K','M'])
    transitions = set(['R','Y'])
    het2 = set(['R','Y','S','W','K','M'])
    het3 = set(['B','D','H','V'])
    for name, comment, seq, qual, isfq in recs:
        L = len(seq)
        # count
        cntA=cntC=cntG=cntT=cnt2=cnt3=cntN=0
        cntTv=cntTs=0
        # for -u, only count uppercase
        for base in seq:
            if count_upper_only and not base.isupper():
                continue
            bup = base.upper()
            if bup == 'A':
                cntA+=1
            elif bup == 'C':
                cntC+=1
            elif bup == 'G':
                cntG+=1
            elif bup == 'T':
                cntT+=1
            elif bup in het2:
                cnt2+=1
                if bup in transversions:
                    cntTv+=1  # col10
                elif bup in transitions:
                    cntTs+=1  # col11
            elif bup in het3:
                cnt3+=1
            elif bup == 'N':
                cntN+=1
            else:
                # unknown, treat as N? but ignore
                pass
        # CpG: count occurrences where seq[i] in {C,Y} and seq[i+1] in {G,R}
        cpg = 0
        cpg_ts = 0
        for i in range(L-1):
            a = seq[i].upper()
            b = seq[i+1].upper()
            if a in ('C','Y') and b in ('G','R'):
                cpg += 2  # as per observed
                # count hets in this CpG for col12
                # if a is Y (het) or b is R (het), count
                # actually both Y and R are transition hets
                # So count number of heteros among the two that are in the CpG pair.
                # For YR both hets => 2, for CR/YG one het =>1
                # But for CG (no het) =>0
                het_in_pair = 0
                if a == 'Y':
                    het_in_pair +=1
                if b == 'R':
                    het_in_pair +=1
                # Note: if a is C (not het) and b is R (het) =>1, etc.
                cpg_ts += het_in_pair
        # cpg already *2, cpg_ts is count as above
        # But col9 is cpg (already 2*), col12 is cpg_ts
        # col10 is cntTv, col11 is cntTs, col12 is cpg_ts
        sys.stdout.write(f"{name}\t{L}\t{cntA}\t{cntC}\t{cntG}\t{cntT}\t{cnt2}\t{cnt3}\t{cntN}\t{cpg}\t{cntTv}\t{cntTs}\t{cpg_ts}\n")
    return 0

