        idx+=1
    if is_fq:
        while idx<n:
            if lines[idx].strip()=="":
                idx+=1; continue
            h=lines[idx].rstrip("\r\n")
            if not h.startswith('@'):
                break
            header=h[1:]
            # name is first word
            if ' ' in header:
                name, comment = header.split(' ',1)
            elif '\t' in header:
                name, comment = header.split('\t',1)
            else:
                name=header; comment=""
