            # need to handle qual shorter than seq: read more lines
            while len(qual) < len(seq) and idx<n and not lines[idx].startswith('@') and not lines[idx].startswith('>') and lines[idx].strip()!="":
                qual+=lines[idx].strip()
                idx+=1
            records.append((name, comment, seq, qual, True))
            # skip empties?
        # remaining as fasta?
        if idx<n:
            remaining="\n".join(lines[idx:])
            if remaining.strip():
                extra=parse_fastx_bytes(remaining.encode())
                records.extend(extra)
    else:
        # FASTA
        name=None
        comment=""
        seq_parts=[]
        while idx<n:
            line=lines[idx].rstrip("\r\n")
            idx+=1
            if line=="":
                continue
            if line.startswith('>'):
                if name is not None:
                    records.append((name, comment, ''.join(seq_parts), None, False))
                header=line[1:]
                if ' ' in header:
                    name, comment = header.split(' ',1)
