            else:
                seq_parts.append(line.strip())
        if name is not None:
            records.append((name, comment, ''.join(seq_parts), None, False))
    return records

def read_fastx(path):
    if path is None or path=="-":
        data=sys.stdin.buffer.read()
        if not data:
            return []
        return parse_fastx_bytes(data)
    else:
        try:
            is_gz=path.endswith(".gz")
            if not is_gz:
                try:
                    with open(path,'rb') as fb:
                        magic=fb.read(2)
                        if magic==b'\x1f\x8b':
                            is_gz=True
                except:
                    pass
            if is_gz:
                with gzip.open(path,'rb') as f:
                    data=f.read()
            else:
                with open(path,'rb') as f:
                    data=f.read()
            return parse_fastx_bytes(data)
        except FileNotFoundError:
            return None
