def cmd_seq(args):
    # manual parse
    def parse_manual(argv):
        o=[]; r=[]
        idx=0
        while idx<len(argv):
            arg=argv[idx]
            if arg=="--":
                r.extend(argv[idx+1:]); break
            if arg.startswith("-") and len(arg)>1 and arg!="-":
                # check combined?
                # if len>2 and first char not requiring arg, treat as combined flags without arg
                flag=arg[1]
                need_arg = flag in ['q','Q','n','l','L','f','s','F','M','X']
                if need_arg:
                    if len(arg)>2:
                        val=arg[2:]
                        o.append((f"-{flag}", val))
                    else:
                        if idx+1 < len(argv) and not argv[idx+1].startswith("-"):
                            val=argv[idx+1]
                            o.append((f"-{flag}", val))
                            idx+=1
                        else:
                            sys.stderr.write(f"seq: option requires an argument -- '{flag}'\n")
                            o.append((f"-{flag}", None))
                else:
                    # flag without arg, may be combined
                    if len(arg)>2:
                        for ch in arg[1:]:
                            if ch in ['a','A','C','N','U','r','R','c','V','S','x']:
                                o.append((f"-{ch}", None))
                            elif ch in ['q','Q','n','l','L','f','s','F','M','X']:
                                sys.stderr.write(f"seq: invalid option -- '{ch}'\n")
                            else:
                                sys.stderr.write(f"seq: invalid option -- '{ch}'\n")
                    else:
                        if flag in ['a','A','C','N','U','r','R','c','V','S','x']:
                            o.append((f"-{flag}", None))
                        elif flag in ['q','Q','n','l','L','f','s','F','M','X']:
                            # already handled
                            pass
                        else:
                            sys.stderr.write(f"seq: invalid option -- '{flag}'\n")
            else:
                r.append(arg)
            idx+=1
        return o,r
    opts, rest = parse_manual(args)
    opt_a=False; opt_A=False; opt_C=False; opt_q=None; opt_Q=33; opt_n=None; opt_l=None; opt_L=None; opt_f=None; opt_s=None; opt_F=None; opt_M=None; opt_N=False; opt_U=False; opt_r=False; opt_R=False; opt_c=False; opt_V=False; opt_S=False; opt_x=False; opt_X=None
    for o,a in opts:
        if o=='-a': opt_a=True
        elif o=='-A': opt_A=True
        elif o=='-C': opt_C=True
        elif o=='-q':
            try:
                opt_q=int(a) if a is not None else None
            except:
                try: opt_q=int(float(a))
                except: opt_q=None
        elif o=='-Q':
            try: opt_Q=int(a)
            except: opt_Q=33
        elif o=='-n': opt_n=a
        elif o=='-l':
            try: opt_l=int(a)
            except: opt_l=0
        elif o=='-L':
            try: opt_L=int(a)
            except: opt_L=0
        elif o=='-f':
            try: opt_f=float(a)
            except: opt_f=None
        elif o=='-s':
            try: opt_s=int(a)
            except: opt_s=11
        elif o=='-F': opt_F=a
        elif o=='-M': opt_M=a
        elif o=='-N': opt_N=True
        elif o=='-U': opt_U=True
        elif o=='-r': opt_r=True
        elif o=='-R': opt_R=True
        elif o=='-c': opt_c=True
        elif o=='-V': opt_V=True
        elif o=='-S': opt_S=True
        elif o=='-x': opt_x=True
        elif o=='-X':
            try: opt_X=int(a) if a is not None else None
            except: opt_X=None
    # input file
    if len(rest)==0:
        recs=read_fastx(None)
    elif len(rest)==1:
        path=rest[0]
        if path=="-":
            recs=read_fastx(None)
        else:
            recs=read_fastx(path)
            if recs is None:
                sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
                return 1
    else:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
        return 1
    if recs is None:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
        return 1
    # random sampler
    rnd = random.Random(opt_s if opt_s is not None else 11) if opt_f is not None else None
    # BED
    bed_intervals={}
    if opt_M:
        try:
            # opt_M may be path
            if os.path.exists(opt_M):
                with open(opt_M) as f:
                    for line in f:
                        if not line.strip() or line.startswith('#'): continue
                        fields=line.strip().split()
                        if len(fields)<3: continue
                        chrom=fields[0]
                        try:
                            s=int(fields[1]); e=int(fields[2])
                        except: continue
                        bed_intervals.setdefault(chrom, []).append((s,e))
            else:
                # try to read as maybe not existent?
                pass
        except: pass
    output_recs=[]
    for name, comment, seq, qual, is_fq in recs:
        orig_seq=seq
        # -L filter
        if opt_L is not None and opt_L!=0:
            if len(seq) < opt_L:
                continue
        if opt_N:
            if 'N' in seq.upper():
                continue
        if opt_C:
            comment=""
        # BED mask
        if opt_M is not None and bed_intervals.get(name):
            seqlist=list(seq)
            for s,e in bed_intervals[name]:
                for idx2 in range(s, e):
                    if 0 <= idx2 < len(seqlist):
                        seqlist[idx2]=seqlist[idx2].lower()
            seq=''.join(seqlist)
        # quality masking
        if opt_q is not None and qual is not None:
            # qual length may differ
            seq_list=list(seq)
            qual_list=list(qual)
            Lmin=min(len(seq_list), len(qual_list))
            for i in range(Lmin):
                phred=ord(qual_list[i]) - opt_Q
                mask=False
                if phred < opt_q:
                    mask=True
                if opt_X is not None and ord(qual_list[i]) > opt_X:
                    mask=True
                if mask:
                    seq_list[i]=seq_list[i].lower()
            seq=''.join(seq_list)
            if opt_n is not None:
                seq_list2=list(seq)
                for i in range(Lmin):
                    phred=ord(qual_list[i]) - opt_Q
                    mask=False
                    if phred < opt_q:
                        mask=True
                    if opt_X is not None and ord(qual_list[i]) > opt_X:
                        mask=True
                    if mask:
                        seq_list2[i]=opt_n
                seq=''.join(seq_list2)
        # -x + -n for lowercases
        if opt_x and opt_n is not None:
            seq_list=list(seq)
            for i,ch in enumerate(orig_seq):
                if ch.islower():
                    if i < len(seq_list):
                        seq_list[i]=opt_n
            seq=''.join(seq_list)
        if opt_U:
            seq=seq.upper()
        # subsampling -f
        if opt_f is not None:
            if 0 < opt_f <= 1:
                if rnd.random() >= opt_f:
                    continue
            elif opt_f <=0:
                continue
            # if >1 treat as keep all (already)
        # revcomp handling
        to_out=[]
        if opt_R:
            rev_seq=revcomp(seq)
            rev_qual=qual[::-1] if qual else None
            to_out.append((f"{name}+", comment, seq, qual, is_fq))
            to_out.append((f"{name}-", comment, rev_seq, rev_qual, is_fq))
        elif opt_r:
            rev_seq=revcomp(seq)
            rev_qual=qual[::-1] if qual else None
            to_out.append((name, comment, rev_seq, rev_qual, is_fq))
        else:
            to_out.append((name, comment, seq, qual, is_fq))
        for oname, ocomment, oseq, oqual, o_isfq in to_out:
            is_fq_out=o_isfq
            if opt_a or opt_A:
                is_fq_out=False
                oqual=None
            if opt_F is not None:
                is_fq_out=True
                oqual=opt_F[0]*len(oseq) if opt_F else 'X'*len(oseq)
            l = opt_l if opt_l is not None else 0
            output_recs.append((oname, ocomment, oseq, oqual, is_fq_out, l))
    for oname, ocomment, oseq, oqual, is_fq_out, l in output_recs:
        hdr=oname
        if ocomment:
            hdr=f"{oname} {ocomment}"
        if l and l>0:
            seq_w="\n".join(oseq[i:i+l] for i in range(0,len(oseq),l))
            if is_fq_out and oqual:
                qual_w="\n".join(oqual[i:i+l] for i in range(0,len(oqual),l))
            else:
                qual_w=oqual
        else:
            seq_w=oseq
            qual_w=oqual
        if is_fq_out:
            if oqual is None:
                oqual='#'*len(oseq)
                qual_w=oqual
            sys.stdout.write(f"@{hdr}\n{seq_w}\n+\n{qual_w}\n")
        else:
            sys.stdout.write(f">{hdr}\n{seq_w}\n")
    return 0

def cmd_sample(args):
    # parse opts -s and -2
    try:
        opts, rest = getopt.getopt(args, "s:2")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"sample: invalid option -- '{bad}'\n")
        sys.stderr.write("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n\n")
        return 1
    seed=11
    two_pass=False
    for o,a in opts:
        if o=='-s':
            try: seed=int(a)
            except: seed=11
        elif o=='-2':
            two_pass=True
    if len(rest)<2:
        sys.stderr.write("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n\n")
        return 1
    infile=rest[0]
    frac_str=rest[1]
    recs=read_fastx(infile)
    if recs is None:
        sys.stderr.write("[E::stk_sample] failed to open the input file/stream.\n")
        return 1
    # determine if fraction or number
    is_frac=False
    try:
        # if contains '.' then fraction, also if 0<val<=1 then fraction?
        val=float(frac_str)
        if '.' in frac_str or (0 < val <= 1):
            # But need to differentiate number like "2" vs fraction  "0.5"
            # We'll treat if val <=1 and ('.' in frac_str or int(val)!=val) => fraction
            # Otherwise if val>1 => number
            if val <=1:
                is_frac=True
            else:
                is_frac=False
        else:
            is_frac=False
            val=int(float(frac_str))
    except:
        is_frac=False
        val=0
    rnd=random.Random(seed)
    if is_frac:
        if two_pass:
            sys.stderr.write("[W::stk_sample] when sampling a fraction, option -2 is ignored.\n")
        frac=val
        out_recs=[]
        for rec in recs:
            if rnd.random() < frac:
                out_recs.append(rec)
        # need to write
        # Determine output format: same as input (fasta or fastq)
        # We'll use input type
        for name, comment, seq, qual, is_fq in out_recs:
            hdr=name + (f" {comment}" if comment else "")
            if is_fq:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0
    else:
        try:
            n=int(float(frac_str))
        except:
            n=0
        # 2-pass mode for number: if -2 then we need reservoir? But we implement simple shuffle
        if two_pass:
            # 2-pass mode for number is supposed to be memory efficient but still pick n random
            # We can implement same as non-2: shuffle and pick n
            pass
        # shuffle using rnd
        # seqtk sample for number picks without replacement randomly
        # Need to handle n >= len(recs): output all? observed sample 10 with 5 gave all
        if n >= len(recs):
            out_recs=recs[:]
            # For determinism, seqtk may shuffle? Earlier sample 10 with 5 gave all in original order? Let's see sample 10 with 5: we saw sample 10 gave all 5 in order? Actually earlier we tested sample 10 with 5 seqs? That gave all 5 in order? Let's check sample 2 gave 2 random order? So for n >= len, just output all in original order? We'll do that
            out_recs=recs
        else:
            # pick n random records: use rnd.sample
            indices=rnd.sample(range(len(recs)), n)
            # Need to preserve original order or random order? In earlier test sample 2 with 5 seqs gave ">seq4\n >seq2"? That appears not sorted, maybe sampled order is random order based on selection order? Let's see sample 2 with 10 seqs earlier gave ">seq4\n >seq5\n" with seed 11? Not clear.
            # We'll output in random order as sampled indices order (as returned by sample, which is random order)
            # But to be safe, we could output in order of appearance? Let's check sample behavior more systematically: sample 2 with 10 seqs produced seq4, seq5 (increasing). That suggests maybe it outputs in order of appearance after reservoir sampling? Let's test again with sample 2 seed 11 for 10 seqs and see output order.
            # For now, we will output in the random selection order but sorted? We'll use sample order.
            out_recs=[recs[i] for i in indices]
            # There is also -2 effect: but we ignore
        for name, comment, seq, qual, is_fq in out_recs:
            hdr=name + (f" {comment}" if comment else "")
            if is_fq:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0

def cmd_subseq(args):
    try:
        opts, rest = getopt.getopt(args, "tsl:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"subseq: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.\n")
        return 1
    opt_t=False; opt_s=False; opt_l=0
    for o,a in opts:
        if o=='-t': opt_t=True
        elif o=='-s': opt_s=True
        elif o=='-l':
            try: opt_l=int(a)
            except: opt_l=0
    if len(rest)<2:
        sys.stderr.write("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.\n")
        return 1
    in_fa=rest[0]; in_bed=rest[1]
    recs=read_fastx(in_fa)
    if recs is None:
        sys.stderr.write("[E::stk_subseq] failed to open the input file/stream.\n")
        return 1
    # read bed/name list
    # try to read second file as text
    try:
        if in_bed.endswith(".gz"):
            with gzip.open(in_bed,'rt') as f:
                bed_lines=[l.rstrip('\n') for l in f]
        else:
            with open(in_bed,'r') as f:
                bed_lines=[l.rstrip('\n') for l in f]
    except:
        sys.stderr.write("[E::stk_subseq] failed to open the input file/stream.\n")
        return 1
    # Determine if BED or name list: if any line has >=3 cols and col2,3 are integers and first col matches a seq name, then BED
    is_bed=False
    for line in bed_lines:
        if not line.strip() or line.startswith('#'): continue
        fields=line.strip().split()
        if len(fields)>=3:
            try:
                int(fields[1]); int(fields[2])
                # check if first field matches any rec name
                # If any such line, treat as BED
                is_bed=True
                break
            except: continue
        # else not bed
    # Build dict for name list if not bed
    rec_dict={name: (name,comment,seq,qual,isfq) for name,comment,seq,qual,isfq in recs}
    if not is_bed:
        # name list: each line first word is name
        wanted=set()
        for line in bed_lines:
            if not line.strip(): continue
            fields=line.strip().split()
            wanted.add(fields[0])
        for name in wanted:
            # need to preserve input order as per file? We'll iterate over recs in order and output if wanted
            pass
        # output in order of appearance in BED file? Actually for name list, output order should be as per BED file order, with possible duplicates?
        for line in bed_lines:
            if not line.strip(): continue
            key=line.strip().split()[0]
            if key in rec_dict:
                rec=rec_dict[key]
                if opt_t:
                    # TAB: name start seq? But for name list, TAB output would be name seq?
                    # Original used -t for BED; for name list, maybe still output FASTA?
                    # We'll fallback to FASTA
                    name2,comment2,seq2,qual2,isfq2=rec
                    if opt_t:
                        # output TAB: name, seq?
                        # We'll output name and seq tab
                        sys.stdout.write(f"{name2}\t{seq2}\n")
                    else:
                        if isfq2:
                            hdr=name2 + (f" {comment2}" if comment2 else "")
                            sys.stdout.write(f"@{hdr}\n{seq2}\n+\n{qual2}\n")
                        else:
                            hdr=name2 + (f" {comment2}" if comment2 else "")
                            if opt_l and opt_l>0:
                                seqw="\n".join(seq2[i:i+opt_l] for i in range(0,len(seq2),opt_l))
                            else:
                                seqw=seq2
                            sys.stdout.write(f">{hdr}\n{seqw}\n")
        return 0
    else:
        # BED mode
        # Build dict for quick
        for line in bed_lines:
            if not line.strip() or line.startswith('#'): continue
            fields=line.strip().split()
            if len(fields)<3: continue
            chrom=fields[0]
            try:
                start=int(fields[1]); end=int(fields[2])
            except: continue
            # optional strand field 5 maybe?
            strand='+'
            if len(fields)>=6:
                strand=fields[5]
            elif len(fields)>=4:
                # sometimes 4th field maybe strand?
                # we check if fields[3] in '+-' and len==4
                if fields[3] in ('+','-'):
                    strand=fields[3]
            if chrom not in rec_dict:
                continue
            name0,comment0,seq0,qual0,isfq0=rec_dict[chrom]
            # extract subsequence
            sub_seq=seq0[start:end]
            sub_qual=qual0[start:end] if qual0 else None
            if opt_s and strand=='-':
                sub_seq=revcomp(sub_seq)
                if sub_qual:
                    sub_qual=sub_qual[::-1]
            # output
            if opt_t:
                # TAB delimited: chrom start sub_seq? Actually observed: "seq1\t2\tCGT" for BED 1-4 -> chrom 1 pos+1 seq?
                # BED start+1 is 2, seq CGT
                # So output is "chrom\tstart+1\tSEQ"
                # If strand, maybe plus?
                sys.stdout.write(f"{chrom}\t{start+1}\t{sub_seq}\n")
            else:
                out_name=f"{chrom}:{start+1}-{end}"
                # include strand? not
                if isfq0 and qual0:
                    # output FASTQ? Need to decide: if original is FASTQ, output FASTQ? Probably yes.
                    # We'll output FASTQ if original is FASTQ
                    hdr=out_name
                    if opt_l and opt_l>0:
                        sub_seq_w="\n".join(sub_seq[i:i+opt_l] for i in range(0,len(sub_seq),opt_l))
                        sub_qual_w="\n".join(sub_qual[i:i+opt_l] for i in range(0,len(sub_qual),opt_l)) if sub_qual else sub_qual
                    else:
                        sub_seq_w=sub_seq
                        sub_qual_w=sub_qual
                    sys.stdout.write(f"@{hdr}\n{sub_seq_w}\n+\n{sub_qual_w}\n")
                else:
                    hdr=out_name
                    if opt_l and opt_l>0:
                        sub_seq_w="\n".join(sub_seq[i:i+opt_l] for i in range(0,len(sub_seq),opt_l))
                    else:
                        sub_seq_w=sub_seq
                    sys.stdout.write(f">{hdr}\n{sub_seq_w}\n")
        return 0

def cmd_fqchk(args):
    try:
        opts,rest=getopt.getopt(args,"q:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"fqchk: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    qthres=20
    for o,a in opts:
        if o=='-q':
            try: qthres=int(a)
            except: qthres=20
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_fqchk] failed to open the input file/stream.\n")
        return 1
    # filter only fastq records?
    fq_recs=[r for r in recs if r[4] and r[3] is not None]
    if not fq_recs:
        # still need to output something? If no fastq, min_len maybe 0?
        sys.stdout.write("min_len: 0; max_len: 0; avg_len: 0.00; 0 distinct quality values\n")
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
        return 0
    lengths=[len(seq) for _,_,seq,_,_ in fq_recs]
    min_len=min(lengths); max_len=max(lengths); avg_len=sum(lengths)/len(lengths)
    # distinct quality values
    all_quals=set()
    for _,_,seq,qual,_ in fq_recs:
        for ch in qual:
            all_quals.add(ord(ch))
    distinct=len(all_quals)
    sys.stdout.write(f"min_len: {min_len}; max_len: {max_len}; avg_len: {avg_len:.2f}; {distinct} distinct quality values\n")
    # header: depending on qthres ==0, last two columns are %Q0 %Q40 etc? Observed: q0 header ends with %Q0 %Q40, otherwise %low %high
    if qthres==0:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%Q0\t%Q40\n")
        header_low_high=False
    else:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
        header_low_high=True
    # per position stats
    max_pos=max_len
    # For each position 1..max
    # Compute per position base counts and quality
    # Need to compute for ALL bases overall
    total_bases=sum(lengths)
    total_A=total_C=total_G=total_T=total_N=0
    total_qual=0
    total_err=0
    low_total=0
    high_total=0
    # For each pos, we will compute
    pos_stats=[]
    for p in range(max_len):
        cntA=cntC=cntG=cntT=cntN=0
        qual_sum=0; err_sum=0; low=0; high=0
        bese=0
        for name,comment,seq,qual,isfq in fq_recs:
            if p < len(seq):
                base=seq[p].upper()
                if base=='A': cntA+=1
                elif base=='C': cntC+=1
                elif base=='G': cntG+=1
                elif base=='T': cntT+=1
                elif base=='N': cntN+=1
                # quality
                q=ord(qual[p]) -33 if p < len(qual) else 0
                qual_sum+=q
                err_sum+= 10**(-q/10) if q>=0 else 1
                bese+=1
                if q < qthres:
                    low+=1
                else:
                    high+=1
        # overall aggregates for ALL row
        total_A+=cntA; total_C+=cntC; total_G+=cntG; total_T+=cntT; total_N+=cntN
        total_qual+=qual_sum
        total_err+=err_sum
        low_total+=low; high_total+=high
        # percentages
