def cmd_mergepe(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mergepe <in1.fq> <in2.fq>\n")
        return 1
    f1=args[0]; f2=args[1]
    recs1=read_fastx(f1)
    recs2=read_fastx(f2)
    if recs1 is None or recs2 is None:
        sys.stderr.write("[E::stk_mergepe] failed to open the input file/stream.\n")
        return 1
    # Interleave: output rec1[0], rec2[0], rec1[1], rec2[1]...
    max_n=max(len(recs1), len(recs2))
    out=[]
    for i in range(max_n):
        if i < len(recs1):
            out.append(recs1[i])
        if i < len(recs2):
            out.append(recs2[i])
    # Write: preserve format (FASTQ if input is FASTQ)
    for name,comment,seq,qual,isfq in out:
        hdr=name + (f" {comment}" if comment else "")
        if isfq and qual:
            sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
        else:
            sys.stdout.write(f">{hdr}\n{seq}\n")
    return 0

def cmd_split(args):
    try:
        opts,rest=getopt.getopt(args, "n:l:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"split: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    n_files=10; line_len=0
    for o,a in opts:
        if o=='-n':
            try: n_files=int(a)
            except: n_files=10
        elif o=='-l':
            try: line_len=int(a)
            except: line_len=0
    if len(rest)<2:
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    prefix=rest[0]; infile=rest[1]
    recs=read_fastx(infile)
    if recs is None:
        sys.stderr.write("[E::stk_split] failed to open the input file/stream.\n")
        return 1
    # create n_files
    # determine extension: .fa
    handles=[]
    for i in range(n_files):
        fname=f"{prefix}.{i+1:05d}.fa"
        # Determine if need to handle gz? No
        # Ensure directory exists
        d=os.path.dirname(fname)
        if d and not os.path.exists(d):
            os.makedirs(d, exist_ok=True)
        handles.append(open(fname,'w'))
    for idx, rec in enumerate(recs):
        name,comment,seq,qual,isfq = rec
        hdr=name + (f" {comment}" if comment else "")
        fid= idx % n_files
        h=handles[fid]
        if isfq and qual:
            # split should output same format? But split's -l may wrap.
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
                qual_w="\n".join(qual[i:i+line_len] for i in range(0,len(qual),line_len))
            else:
                seq_w=seq; qual_w=qual
            h.write(f"@{hdr}\n{seq_w}\n+\n{qual_w}\n")
        else:
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
            else:
                seq_w=seq
            h.write(f">{hdr}\n{seq_w}\n")
    for h in handles: h.close()
    return 0

