        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"gc: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]\n")
        return 1
    highAT=False; f=0.6; l=20; xdrop=10.0
    for o,a in opts:
        if o=='-w': highAT=True
        elif o=='-f':
            try: f=float(a)
            except: f=0.6
        elif o=='-l':
            try: l=int(a)
            except: l=20
        elif o=='-x':
            try: xdrop=float(a)
            except: xdrop=10.0
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_gc] failed to open the input file/stream.\n")
        return 1
    # Simplified GC detection: find regions where GC fraction >= f (or AT fraction if -w)
    # Use sliding window maybe with X-dropoff? We'll implement simple scan: iterate, find contiguous region where GC >= f and length >= l.
    # For simplicity, just scan whole sequence: compute GC fraction for each possible window? Instead, find maximal regions.
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        # We'll use simple: find regions by scanning and using average GC.
        # We'll treat 'G','C' as GC, 'A','T' as AT, others as ignored?
        # For highAT, AT fraction.
        is_gc = lambda b: b.upper() in ('G','C')
        is_at = lambda b: b.upper() in ('A','T')
        # Use method: sliding window with X-drop: maintain best GC-rich region
        # Simplified: just report whole sequence if its GC >= f and length>=l
        total_gc = sum(1 for b in seq if is_gc(b))
        total_at = sum(1 for b in seq if is_at(b))
        total_valid = sum(1 for b in seq if b.upper() in ('A','C','G','T'))
        if total_valid==0:
            continue
        gc_frac = total_gc / total_valid if total_valid else 0
        at_frac = total_at / total_valid if total_valid else 0
        target_frac = at_frac if highAT else gc_frac
        if target_frac >= f and L >= l:
            # Report: name start end something? Observed gc output: "s\t0\t100\t100"
            # Format: chr start end length? Actually with input length 100 high GC gave "s\t0\t100\t100"
            # So columns: name, start, end, length?
            sys.stdout.write(f"{name}\t0\t{L}\t{L}\n")
        else:
            # otherwise no output
            pass
    return 0

def cmd_mutfa(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        return 1
    fa_path=args[0]; snp_path=args[1]
    recs=read_fastx(fa_path)
    if recs is None:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    # read snp file
    snps={}
    try:
        if snp_path.endswith(".gz"):
            open_func=gzip.open
            mode='rt'
        else:
            open_func=open
            mode='r'
        with open_func(snp_path, mode) as f:
            for line in f:
                if not line.strip() or line.startswith('#'): continue
                fields=line.strip().split()
                if len(fields)<4: continue
                chrom=fields[0]
                try: pos=int(fields[1])
                except: continue
                base=fields[3]
                # store
                snps.setdefault(chrom, {})[pos]=base
    except:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    # apply mutations
    for name,comment,seq,qual,isfq in recs:
        seqlist=list(seq)
        if name in snps:
            for pos, base in snps[name].items():
                idx=pos-1
                if 0 <= idx < len(seqlist):
                    seqlist[idx]=base.upper() if seqlist[idx].isupper() else base.lower() if seqlist[idx].islower() else base
                # if position beyond len, ignore?
        new_seq=''.join(seqlist)
        hdr=name + (f" {comment}" if comment else "")
        sys.stdout.write(f">{hdr}\n{new_seq}\n")
    return 0

