    transversions=set(['S','W','K','M'])
    transitions=set(['R','Y'])
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        cntA=cntC=cntG=cntT=cnt2=cnt3=cntN=0
        cntTv=cntTs=0
        for base in seq:
            if count_upper_only and not base.isupper():
                continue
            up=base.upper()
            if up=='A': cntA+=1
            elif up=='C': cntC+=1
            elif up=='G': cntG+=1
            elif up=='T': cntT+=1
            elif up in het2:
                cnt2+=1
                if up in transversions: cntTv+=1
                elif up in transitions: cntTs+=1
            elif up in het3: cnt3+=1
            elif up=='N': cntN+=1
        cpg=0; cpg_ts=0
        for i in range(L-1):
            a=seq[i].upper(); b=seq[i+1].upper()
            if a in ('C','Y') and b in ('G','R'):
                cpg+=2
                het=0
                if a=='Y': het+=1
                if b=='R': het+=1
                cpg_ts+=het
        sys.stdout.write(f"{name}\t{L}\t{cntA}\t{cntC}\t{cntG}\t{cntT}\t{cnt2}\t{cnt3}\t{cntN}\t{cpg}\t{cntTv}\t{cntTs}\t{cpg_ts}\n")
    return 0

def cmd_seq(args):
    def parse_manual(argv):
        o=[]; r=[]
        idx=0
        while idx<len(argv):
            arg=argv[idx]
            if arg=="--":
                r.extend(argv[idx+1:]); break
            if arg.startswith("-") and len(arg)>1 and arg!="-":
                flag=arg[1]
                need_arg=flag in ['q','Q','n','l','L','f','s','F','M','X']
                if need_arg:
                    if len(arg)>2:
                        val=arg[2:]
                        o.append((f"-{flag}",val))
                    else:
                        if idx+1<len(argv) and not argv[idx+1].startswith("-"):
                            val=argv[idx+1]
                            o.append((f"-{flag}",val)); idx+=1
                        else:
                            sys.stderr.write(f"seq: option requires an argument -- '{flag}'\n")
                            o.append((f"-{flag}",None))
                else:
                    if len(arg)>2:
                        for ch in arg[1:]:
                            if ch in ['a','A','C','N','U','r','R','c','V','S','x']:
                                o.append((f"-{ch}",None))
                            elif ch in ['q','Q','n','l','L','f','s','F','M','X']:
                                sys.stderr.write(f"seq: invalid option -- '{ch}'\n")
                            else:
                                sys.stderr.write(f"seq: invalid option -- '{ch}'\n")
                    else:
                        if flag in ['a','A','C','N','U','r','R','c','V','S','x']:
                            o.append((f"-{flag}",None))
                        elif flag in ['q','Q','n','l','L','f','s','F','M','X']:
                            pass
                        else:
                            sys.stderr.write(f"seq: invalid option -- '{flag}'\n")
            else:
                r.append(arg)
            idx+=1
        return o,r
    opts,rest=parse_manual(args)
    opt_a=False; opt_A=False; opt_C=False; opt_q=None; opt_Q=33; opt_n=None; opt_l=None; opt_L=None; opt_f=None; opt_s=None; opt_F=None; opt_M=None; opt_N=False; opt_U=False; opt_r=False; opt_R=False; opt_c=False; opt_V=False; opt_S=False; opt_x=False; opt_X=None
    for o,a in opts:
        if o=='-a': opt_a=True
        elif o=='-A': opt_A=True
        elif o=='-C': opt_C=True
        elif o=='-q':
            try: opt_q=int(a) if a is not None else None
            except:
                try: opt_q=int(float(a))
                except: opt_q=None
        elif o=='-Q':
            try: opt_Q=int(a)
            except: opt_Q=33
        elif o=='-n': opt_n=a
        elif o=='-l':
            try: opt_l=int(a)
            except: opt_l=0
        elif o=='-L':
            try: opt_L=int(a)
            except: opt_L=0
        elif o=='-f':
            try: opt_f=float(a)
            except: opt_f=None
        elif o=='-s':
            try: opt_s=int(a)
            except: opt_s=11
        elif o=='-F': opt_F=a
        elif o=='-M': opt_M=a
        elif o=='-N': opt_N=True
        elif o=='-U': opt_U=True
        elif o=='-r': opt_r=True
        elif o=='-R': opt_R=True
        elif o=='-c': opt_c=True
        elif o=='-V': opt_V=True
        elif o=='-S': opt_S=True
        elif o=='-x': opt_x=True
        elif o=='-X':
            try: opt_X=int(a) if a is not None else None
            except: opt_X=None
    if len(rest)==0:
        recs=read_fastx(None)
    elif len(rest)==1:
        path=rest[0]
        if path=="-":
            recs=read_fastx(None)
        else:
            recs=read_fastx(path)
            if recs is None:
                sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
                return 1
    else:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
        return 1
    if recs is None:
        sys.stderr.write("[E::stk_seq] failed to open the input file/stream.\n")
        return 1
    rnd=random.Random(opt_s if opt_s is not None else 11) if opt_f is not None else None
    bed_intervals={}
    if opt_M and os.path.exists(opt_M):
        try:
            with open(opt_M) as f:
                for line in f:
                    if not line.strip() or line.startswith('#'): continue
                    fields=line.strip().split()
                    if len(fields)<3: continue
                    chrom=fields[0]
                    try:
                        s=int(fields[1]); e=int(fields[2])
                    except: continue
                    bed_intervals.setdefault(chrom,[]).append((s,e))
        except: pass
    output_recs=[]
    for name,comment,seq,qual,isfq in recs:
        orig_seq=seq
        if opt_L is not None and opt_L!=0:
            if len(seq) < opt_L:
                continue
        if opt_N and 'N' in seq.upper():
            continue
        if opt_C:
            comment=""
        if opt_M is not None and name in bed_intervals:
            lst=list(seq)
            for s,e in bed_intervals[name]:
                for idx2 in range(s,e):
                    if 0 <= idx2 < len(lst):
                        lst[idx2]=lst[idx2].lower()
            seq=''.join(lst)
        if opt_q is not None and qual is not None:
            seq_list=list(seq)
            qual_list=list(qual)
            Lmin=min(len(seq_list),len(qual_list))
            for i in range(Lmin):
                phred=ord(qual_list[i]) - opt_Q
                mask=False
                if phred < opt_q: mask=True
                if opt_X is not None and ord(qual_list[i]) > opt_X: mask=True
                if mask: seq_list[i]=seq_list[i].lower()
            seq=''.join(seq_list)
            if opt_n is not None:
                seq_list2=list(seq)
                for i in range(Lmin):
                    phred=ord(qual_list[i]) - opt_Q
                    mask=False
                    if phred < opt_q: mask=True
                    if opt_X is not None and ord(qual_list[i]) > opt_X: mask=True
                    if mask: seq_list2[i]=opt_n
                seq=''.join(seq_list2)
        if opt_x and opt_n is not None:
            lst=list(seq)
            for i,ch in enumerate(orig_seq):
                if ch.islower():
                    if i < len(lst):
                        lst[i]=opt_n
            seq=''.join(lst)
        if opt_U:
            seq=seq.upper()
        if opt_f is not None:
            if 0 < opt_f <= 1:
                if rnd.random() >= opt_f:
                    continue
            elif opt_f <=0:
                continue
        to_out=[]
        if opt_R:
            rev_seq=revcomp(seq)
            rev_qual=qual[::-1] if qual else None
            to_out.append((f"{name}+",comment,seq,qual,isfq))
            to_out.append((f"{name}-",comment,rev_seq,rev_qual,isfq))
        elif opt_r:
            rev_seq=revcomp(seq)
            rev_qual=qual[::-1] if qual else None
            to_out.append((name,comment,rev_seq,rev_qual,isfq))
        else:
            to_out.append((name,comment,seq,qual,isfq))
        for oname,ocomment,oseq,oqual,o_isfq in to_out:
            is_fq_out=o_isfq
            if opt_a or opt_A:
                is_fq_out=False
                oqual=None
            if opt_F is not None:
                is_fq_out=True
                oqual=opt_F[0]*len(oseq) if opt_F else 'X'*len(oseq)
            l = opt_l if opt_l is not None else 0
            output_recs.append((oname,ocomment,oseq,oqual,is_fq_out,l))
    for oname,ocomment,oseq,oqual,is_fq_out,l in output_recs:
        hdr=oname + (f" {ocomment}" if ocomment else "")
        if l and l>0:
            seq_w="\n".join(oseq[i:i+l] for i in range(0,len(oseq),l))
            if is_fq_out and oqual:
                qual_w="\n".join(oqual[i:i+l] for i in range(0,len(oqual),l))
            else:
                qual_w=oqual
        else:
            seq_w=oseq
            qual_w=oqual
        if is_fq_out:
            if oqual is None:
                oqual='#'*len(oseq)
                qual_w=oqual
            sys.stdout.write(f"@{hdr}\n{seq_w}\n+\n{qual_w}\n")
        else:
            sys.stdout.write(f">{hdr}\n{seq_w}\n")
    return 0

# Dummy sample with Python random (will not exactly match but close)
def cmd_sample(args):
    try:
        opts,rest=getopt.getopt(args,"s:2")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"sample: invalid option -- '{bad}'\n")
        sys.stderr.write("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n\n")
        return 1
    seed=11; two_pass=False
    for o,a in opts:
        if o=='-s':
            try: seed=int(a)
            except: seed=11
        elif o=='-2': two_pass=True
    if len(rest)<2:
        sys.stderr.write("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n\n")
        return 1
    infile=rest[0]; frac_str=rest[1]
    recs=read_fastx(infile)
    if recs is None:
        sys.stderr.write("[E::stk_sample] failed to open the input file/stream.\n")
        return 1
    is_frac=False; val=0
    try:
        v=float(frac_str)
        if '.' in frac_str or (0 < v <= 1 and v!=int(v)):
            is_frac=(0 < v <= 1)
            if is_frac: val=v
            else: val=int(v)
        else:
            if v <= 1 and '.' not in frac_str:
                # Could be integer fraction? e.g., "1" is not frac? Actually sample 1 means 1 read? But also fraction 1 means 100%? Treat as number if integer and >1? ambiguous.
                # For simplicity, if frac_str contains '.' then fraction, else if v<=1 and integer 0/1 -> fraction?
                is_frac=False
                val=int(v)
            else:
                is_frac=False
                val=int(v)
    except:
        is_frac=False
        val=0
    # more robust: if frac_str starts with "0." then fraction, else if "." in frac_str then fraction, else if 0<v<1 then fraction else number
    # Re-evaluate: if frac_str contains '.' then fraction else if 0<float<1 then maybe fraction? But "0.5" has dot.
    # So our earlier logic stands
    # Try to handle correctly: use string check
    if '.' in frac_str:
        try:
            v=float(frac_str)
            if 0 < v <= 1:
                is_frac=True
                val=v
            else:
                is_frac=False
                val=int(v)
        except: pass
    else:
        # no dot, treat as number if integer
        try:
            val=int(frac_str)
            is_frac=False
        except:
            is_frac=False
    rnd=random.Random(seed)
    if is_frac:
        if two_pass:
            sys.stderr.write("[W::stk_sample] when sampling a fraction, option -2 is ignored.\n")
        frac=val
        out=[]
        for rec in recs:
            if rnd.random() < frac:
                out.append(rec)
        for name,comment,seq,qual,isfq in out:
            hdr=name + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0
    else:
        try: n=int(float(frac_str))
        except: n=0
        if n >= len(recs):
            out=recs
        else:
            # Use Python's sample but need to mimic seqtk's order: seqtk's sample for number with seed produces order that is not sorted but is the order of reservoir sampling?
            # We will implement simple: rnd.sample and then sort by original order? But observed sample 2 with seed 11 gave [4,2] not sorted. Python's sample gave [3,4] not match. So we just use rnd.sample
            # To get closer, we will use random.sample
            indices=rnd.sample(range(len(recs)), n)
            out=[recs[i] for i in indices]
        for name,comment,seq,qual,isfq in out:
            hdr=name + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0

