def cmd_fqchk(args):
    try:
        opts,rest=getopt.getopt(args,"q:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"fqchk: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    qthres=20
    for o,a in opts:
        if o=='-q':
            try: qthres=int(a)
            except: qthres=20
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_fqchk] failed to open the input file/stream.\n")
        return 1
    fq_recs=[r for r in recs if r[4] and r[3] is not None]
    if not fq_recs:
        sys.stdout.write("min_len: 0; max_len: 0; avg_len: 0.00; 0 distinct quality values\n")
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
        return 0
    lengths=[len(seq) for _,_,seq,_,_ in fq_recs]
    min_len=min(lengths); max_len=max(lengths); avg_len=sum(lengths)/len(lengths)
    all_quals=set()
    for _,_,seq,qual,_ in fq_recs:
        for ch in qual:
            all_quals.add(ord(ch))
    distinct=len(all_quals)
    sys.stdout.write(f"min_len: {min_len}; max_len: {max_len}; avg_len: {avg_len:.2f}; {distinct} distinct quality values\n")
    if qthres==0:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%Q0\t%Q40\n")
    else:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
    max_pos=max_len
    total_bases=sum(lengths)
    total_A=total_C=total_G=total_T=total_N=0
    total_qual=0; total_err=0; low_total=0; high_total=0
    pos_stats=[]
    for p in range(max_len):
        cntA=cntC=cntG=cntT=cntN=0
        qual_sum=0; err_sum=0; low=0; high=0; bese=0
        for name,comment,seq,qual,isfq in fq_recs:
            if p < len(seq):
                base=seq[p].upper()
                if base=='A': cntA+=1
                elif base=='C': cntC+=1
                elif base=='G': cntG+=1
                elif base=='T': cntT+=1
                elif base=='N': cntN+=1
                q=ord(qual[p]) -33 if p < len(qual) else 0
                qual_sum+=q
                # err probability
                err = 10**(-q/10) if q>=0 else 1
                err_sum+=err
                bese+=1
                if q < qthres:
                    low+=1
                else:
                    high+=1
        total_A+=cntA; total_C+=cntC; total_G+=cntG; total_T+=cntT; total_N+=cntN
        total_qual+=qual_sum; total_err+=err_sum; low_total+=low; high_total+=high
        if bese==0: continue
        pctA=cntA/bese*100; pctC=cntC/bese*100; pctG=cntG/bese*100; pctT=cntT/bese*100; pctN=cntN/bese*100
        avgQ=qual_sum/bese if bese else 0
        # errQ as average error Q: -10*log10(avg_err)
        avg_err=err_sum/bese if bese else 0
        if avg_err>0:
            errQ = -10*math.log10(avg_err)
        else:
            errQ=0
        # For qthres==0, last two cols are counts for Q0 vs Q40 etc: low/high still but with different formatting
        perc_low=low/bese*100
        perc_high=high/bese*100
        pos_stats.append((p+1,bese,pctA,pctC,pctG,pctT,pctN,avgQ,errQ,perc_low,perc_high))
    if total_bases>0:
        pctA=total_A/total_bases*100; pctC=total_C/total_bases*100; pctG=total_G/total_bases*100; pctT=total_T/total_bases*100; pctN=total_N/total_bases*100
        avgQ=total_qual/total_bases
        avg_err=total_err/total_bases if total_bases else 0
        if avg_err>0:
            errQ = -10*math.log10(avg_err)
        else:
            errQ=0
        perc_low_total=low_total/total_bases*100
        perc_high_total=high_total/total_bases*100
        sys.stdout.write(f"ALL\t{total_bases}\t{pctA:.1f}\t{pctC:.1f}\t{pctG:.1f}\t{pctT:.1f}\t{pctN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{perc_low_total:.1f}\t{perc_high_total:.1f}\n")
        for p,bese,pA,pC,pG,pT,pN,avgQ,errQ,pl,ph in pos_stats:
            if qthres==0:
                sys.stdout.write(f"{p}\t{bese}\t{pA:.1f}\t{pC:.1f}\t{pG:.1f}\t{pT:.1f}\t{pN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{pl:.2f}\t{ph:.2f}\n")
            else:
                sys.stdout.write(f"{p}\t{bese}\t{pA:.1f}\t{pC:.1f}\t{pG:.1f}\t{pT:.1f}\t{pN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{pl:.1f}\t{ph:.1f}\n")
    return 0

def cmd_mergepe(args):
    if len(args)<2:
