def cmd_split(args):
    try:
        opts,rest=getopt.getopt(args,"n:l:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"split: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    n_files=10; line_len=0
    for o,a in opts:
        if o=='-n':
            try: n_files=int(a)
            except: n_files=10
        elif o=='-l':
            try: line_len=int(a)
            except: line_len=0
    if len(rest)<2:
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    prefix=rest[0]; infile=rest[1]
    recs=read_fastx(infile)
    if recs is None:
        sys.stderr.write("[E::stk_split] failed to open the input file/stream.\n")
        return 1
    handles=[]
    for i in range(n_files):
        fname=f"{prefix}.{i+1:05d}.fa"
        d=os.path.dirname(fname)
        if d and not os.path.exists(d):
            os.makedirs(d, exist_ok=True)
        handles.append(open(fname,'w'))
    for idx,rec in enumerate(recs):
        name,comment,seq,qual,isfq=rec
        hdr=name + (f" {comment}" if comment else "")
        fid=idx % n_files
        h=handles[fid]
        if isfq and qual:
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
                qual_w="\n".join(qual[i:i+line_len] for i in range(0,len(qual),line_len))
            else:
                seq_w=seq; qual_w=qual
            h.write(f"@{hdr}\n{seq_w}\n+\n{qual_w}\n")
        else:
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
            else:
                seq_w=seq
            h.write(f">{hdr}\n{seq_w}\n")
    for h in handles: h.close()
    return 0

def cmd_trimfq(args):
    try:
        opts,rest=getopt.getopt(args,"q:l:b:e:L:Q")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"trimfq: invalid option -- '{bad}'\n")
        sys.stderr.write("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n\n")
        return 1
    q=0.05; l=30; b=0; e=0; L=0; forceQ=False
    for o,a in opts:
        if o=='-q':
            try: q=float(a)
            except: q=0.05
        elif o=='-l':
            try: l=int(a)
            except: l=30
        elif o=='-b':
            try: b=int(a)
            except: b=0
        elif o=='-e':
            try: e=int(a)
            except: e=0
        elif o=='-L':
            try: L=int(a)
            except: L=0
        elif o=='-Q': forceQ=True
    if len(rest)<1:
        sys.stderr.write("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_trimfq] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        n=len(seq)
        if qual is None and not forceQ:
            # FASTA
            if b!=0 or e!=0 or L!=0:
                start=b
                end=n - e if e!=0 else n
                if L!=0:
                    if b==0 and e==0:
                        start=0; end=min(n,L)
                    else:
                        end=min(end,start+L)
                seq2=seq[start:end]
                sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{seq2}\n")
            else:
                sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{seq}\n")
            continue
        # FASTQ
        if qual is None:
            qual='#'*len(seq)
        if b!=0 or e!=0 or L!=0:
            start=b
            end=n - e if e!=0 else n
            if L!=0:
                if b==0 and e==0:
                    start=0; end=min(n,L)
                else:
                    end=min(end,start+L)
            seq2=seq[start:end]
            qual2=qual[start:end]
        else:
            if q<=0:
                q_phred=100
            else:
                try: q_phred=-10*math.log10(q)
                except: q_phred=20
            left=0; right=n
            while left < right:
                phred=ord(qual[left]) -33
                if phred >= q_phred:
                    break
                left+=1
                if n - left < l: break
            while right > left:
                phred=ord(qual[right-1]) -33
                if phred >= q_phred:
                    break
                right-=1
                if right - left < l: break
            seq2=seq[left:right]
            qual2=qual[left:right]
        hdr=name + (f" {comment}" if comment else "")
        if forceQ or isfq:
            sys.stdout.write(f"@{hdr}\n{seq2}\n+\n{qual2}\n")
        else:
            sys.stdout.write(f">{hdr}\n{seq2}\n")
    return 0

def cmd_hety(args):
    try:
        opts,rest=getopt.getopt(args,"w:t:m")
    except getopt.GetoptError as e:
        sys.stderr.write("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n\n")
        return 1
    w=50000; t=5; m=False
    for o,a in opts:
        if o=='-w':
            try: w=int(a)
            except: w=50000
        elif o=='-t':
            try: t=int(a)
            except: t=5
        elif o=='-m': m=True
    if len(rest)<1:
        sys.stderr.write("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_hety] failed to open the input file/stream.\n")
        return 1
    het_set=set(['R','Y','S','W','K','M','B','D','H','V'])
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        if L <= w:
            windows=[(0,L)]
        else:
            step=w//t if t>0 else w
            if step==0: step=1
            windows=[]
            start=0
            while start < L:
                end=min(start+w, L)
                windows.append((start,end))
                start+=step
        for ws,we in windows:
            sub=seq[ws:we]
            hets=0; eff=0
            for base in sub:
                if m and base.islower(): continue
                eff+=1
                if base.upper() in het_set: hets+=1
            rate=hets/eff*w if eff>0 else 0
            sys.stdout.write(f"{name}\t{ws}\t{we}\t{rate:.2f}\t{eff}\t{hets}\n")
    return 0

def cmd_gc(args):
    try:
        opts,rest=getopt.getopt(args,"wf:l:x:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"gc: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]\n")
        return 1
    highAT=False; f=0.6; l=20; xdrop=10.0
    for o,a in opts:
        if o=='-w': highAT=True
        elif o=='-f':
            try: f=float(a)
            except: f=0.6
        elif o=='-l':
            try: l=int(a)
            except: l=20
        elif o=='-x':
            try: xdrop=float(a)
            except: xdrop=10.0
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_gc] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        total_gc=sum(1 for b in seq if b.upper() in ('G','C'))
        total_at=sum(1 for b in seq if b.upper() in ('A','T'))
        total_valid=sum(1 for b in seq if b.upper() in ('A','C','G','T'))
        if total_valid==0: continue
        gc_frac=total_gc/total_valid if total_valid else 0
        at_frac=total_at/total_valid if total_valid else 0
        target=at_frac if highAT else gc_frac
        if target >= f and L >= l:
            sys.stdout.write(f"{name}\t0\t{L}\t{L}\n")
    return 0

def cmd_mutfa(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        return 1
    fa_path=args[0]; snp_path=args[1]
    recs=read_fastx(fa_path)
    if recs is None:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    snps={}
    try:
        if snp_path.endswith(".gz"):
            open_func=gzip.open; mode='rt'
        else:
            open_func=open; mode='r'
        with open_func(snp_path, mode) as f:
            for line in f:
                if not line.strip() or line.startswith('#'): continue
                fields=line.strip().split()
                if len(fields)<4: continue
                chrom=fields[0]
                try: pos=int(fields[1])
                except: continue
                base=fields[3]
                snps.setdefault(chrom,{})[pos]=base
    except:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        lst=list(seq)
        if name in snps:
            for pos,base in snps[name].items():
                idx=pos-1
                if 0 <= idx < len(lst):
                    lst[idx]=base.upper() if lst[idx].isupper() else base.lower() if lst[idx].islower() else base
        sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{''.join(lst)}\n")
    return 0

def cmd_mergefa(args):
    # manual parse to handle -q with arg
    qthres=0; intersect=False; maskLower=False; random_allele=False; suppress_hets=False
    files=[]
    idx=0
    while idx < len(args):
        if args[idx].startswith('-') and len(args[idx])>1:
            flag=args[idx][1]
            if flag=='q':
                if idx+1 < len(args):
                    try: qthres=int(args[idx+1])
                    except: qthres=0
                    idx+=2; continue
                else: idx+=1; continue
            elif flag=='i': intersect=True
            elif flag=='m': maskLower=True
            elif flag=='r': random_allele=True
            elif flag=='h': suppress_hets=True
            else: pass
        else:
            files.append(args[idx])
        idx+=1
    if len(files)<2:
        sys.stderr.write("\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n\n")
        return 1
    f1=files[-2]; f2=files[-1]
    recs1=read_fastx(f1); recs2=read_fastx(f2)
    if recs1 is None or recs2 is None:
        sys.stderr.write("[E::stk_mergefa] failed to open the input file/stream.\n")
        return 1
    dict2={name:(seq,qual,isfq) for name,comment,seq,qual,isfq in recs2}
    iupac_merge={('A','A'):'A',('C','C'):'C',('G','G'):'G',('T','T'):'T',('A','G'):'R',('G','A'):'R',('C','T'):'Y',('T','C'):'Y',('G','C'):'S',('C','G'):'S',('A','T'):'W',('T','A'):'W',('G','T'):'K',('T','G'):'K',('A','C'):'M',('C','A'):'M',('N','N'):'N'}
    rnd=random.Random(11)
    for name,comment,seq1,qual1,isfq1 in recs1:
        if name not in dict2:
            if intersect: continue
            sys.stdout.write(f">{name}\n{seq1}\n")
            continue
        seq2,qual2,isfq2=dict2[name]
        L=min(len(seq1),len(seq2))
        merged=[]
        same=0; diff=0
        for i in range(L):
            b1=seq1[i].upper(); b2=seq2[i].upper()
            if suppress_hets:
                if b1 in 'RYSWKMBDHV': b1='N'
                if b2 in 'RYSWKMBDHV': b2='N'
            if random_allele:
                het_bases={'R':['A','G'],'Y':['C','T'],'S':['C','G'],'W':['A','T'],'K':['G','T'],'M':['A','C'],'B':['C','G','T'],'D':['A','G','T'],'H':['A','C','T'],'V':['A','C','G']}
                if b1 in het_bases: b1=rnd.choice(het_bases[b1])
                if b2 in het_bases: b2=rnd.choice(het_bases[b2])
            key=(b1,b2)
            if key in iupac_merge: mb=iupac_merge[key]
            elif (b2,b1) in iupac_merge: mb=iupac_merge[(b2,b1)]
            else: mb='N'
            if maskLower and ('N' in (b1,b2)): mb=mb.lower()
            merged.append(mb)
            if b1==b2: same+=1
            else: diff+=1
        sys.stderr.write(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},0,0,0)\n")
        sys.stdout.write(f">{name}\n{''.join(merged)}\n")
    return 0

def cmd_famask(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk famask <src.fa> <mask.fa>\n")
        return 1
    src_path=args[0]; mask_path=args[1]
    recs_src=read_fastx(src_path)
    recs_mask=read_fastx(mask_path)
    if recs_src is None or recs_mask is None:
        sys.stderr.write("[E::stk_famask] failed to open the input file/stream.\n")
        return 1
    mask_dict={name:seq for name,comment,seq,qual,isfq in recs_mask}
    for name,comment,seq,qual,isfq in recs_src:
        mask_seq=mask_dict.get(name)
        if mask_seq is None:
            hdr=name + (f" {comment}" if comment else "")
            sys.stdout.write(f">{hdr}\n{seq}\n")
            continue
        lst=list(seq)
        for i in range(min(len(seq),len(mask_seq))):
            mbase=mask_seq[i]
            if mbase.upper()=='X':
                lst[i]=lst[i].lower()
            elif mbase.islower():
                lst[i]=lst[i].lower()
        hdr=name + (f" {comment}" if comment else "")
        sys.stdout.write(f">{hdr}\n{''.join(lst)}\n")
    return 0

def cmd_dropse(args):
    if len(args)==0:
        recs=read_fastx(None)
        if not recs: return 0
    else:
        recs=read_fastx(args[0])
        if recs is None:
            sys.stderr.write("[E::stk_dropse] failed to open the input file/stream.\n")
            return 1
        if not recs: return 0
    from collections import defaultdict
    groups=defaultdict(list)
    for rec in recs:
        name=rec[0]
        base=name
        if base.endswith("/1") or base.endswith("/2") or base.endswith(".1") or base.endswith(".2"):
            base=base[:-2]
        groups[base].append(rec)
    keep=set()
    for base,lst in groups.items():
        if len(lst)==2:
            names=[r[0] for r in lst]
            suffixes=set()
            for n in names:
                if n.endswith("/1"): suffixes.add("1")
                elif n.endswith("/2"): suffixes.add("2")
                elif n.endswith(".1"): suffixes.add("1")
                elif n.endswith(".2"): suffixes.add("2")
                else: suffixes.add("?")
            if suffixes=={"1","2"}:
                keep.add(base)
            elif len(set(names))==1:
                keep.add(base)
    for rec in recs:
        name=rec[0]
        base=name
        if base.endswith("/1") or base.endswith("/2") or base.endswith(".1") or base.endswith(".2"):
            base=base[:-2]
        if base in keep:
            n,comment,seq,qual,isfq=rec
            hdr=n + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
    return 0

