    if recs is None:
        sys.stderr.write("[E::stk_sample] failed to open the input file/stream.\n")
        return 1
    is_frac=False; val=0
    try:
        v=float(frac_str)
        if '.' in frac_str or (0 < v <= 1 and v!=int(v)):
            is_frac=(0 < v <= 1)
            if is_frac: val=v
            else: val=int(v)
        else:
            if v <= 1 and '.' not in frac_str:
                # Could be integer fraction? e.g., "1" is not frac? Actually sample 1 means 1 read? But also fraction 1 means 100%? Treat as number if integer and >1? ambiguous.
                # For simplicity, if frac_str contains '.' then fraction, else if v<=1 and integer 0/1 -> fraction?
                is_frac=False
                val=int(v)
            else:
                is_frac=False
                val=int(v)
    except:
        is_frac=False
        val=0
    # more robust: if frac_str starts with "0." then fraction, else if "." in frac_str then fraction, else if 0<v<1 then fraction else number
    # Re-evaluate: if frac_str contains '.' then fraction else if 0<float<1 then maybe fraction? But "0.5" has dot.
    # So our earlier logic stands
    # Try to handle correctly: use string check
    if '.' in frac_str:
        try:
            v=float(frac_str)
            if 0 < v <= 1:
                is_frac=True
                val=v
            else:
                is_frac=False
                val=int(v)
        except: pass
    else:
        # no dot, treat as number if integer
        try:
            val=int(frac_str)
            is_frac=False
        except:
            is_frac=False
    rnd=random.Random(seed)
    if is_frac:
        if two_pass:
            sys.stderr.write("[W::stk_sample] when sampling a fraction, option -2 is ignored.\n")
        frac=val
        out=[]
        for rec in recs:
            if rnd.random() < frac:
                out.append(rec)
        for name,comment,seq,qual,isfq in out:
            hdr=name + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0
    else:
        try: n=int(float(frac_str))
        except: n=0
        if n >= len(recs):
            out=recs
        else:
            # Use Python's sample but need to mimic seqtk's order: seqtk's sample for number with seed produces order that is not sorted but is the order of reservoir sampling?
            # We will implement simple: rnd.sample and then sort by original order? But observed sample 2 with seed 11 gave [4,2] not sorted. Python's sample gave [3,4] not match. So we just use rnd.sample
            # To get closer, we will use random.sample
            indices=rnd.sample(range(len(recs)), n)
            out=[recs[i] for i in indices]
        for name,comment,seq,qual,isfq in out:
            hdr=name + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
        return 0

def cmd_subseq(args):
    try:
        opts,rest=getopt.getopt(args,"tsl:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"subseq: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.\n")
        return 1
    opt_t=False; opt_s=False; opt_l=0
    for o,a in opts:
        if o=='-t': opt_t=True
        elif o=='-s': opt_s=True
        elif o=='-l':
            try: opt_l=int(a)
            except: opt_l=0
    if len(rest)<2:
        sys.stderr.write("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.\n")
        return 1
    in_fa=rest[0]; in_bed=rest[1]
    recs=read_fastx(in_fa)
    if recs is None:
        sys.stderr.write("[E::stk_subseq] failed to open the input file/stream.\n")
        return 1
    try:
        if in_bed.endswith(".gz"):
            with gzip.open(in_bed,'rt') as f:
                bed_lines=[l.rstrip('\n') for l in f]
        else:
            with open(in_bed,'r') as f:
                bed_lines=[l.rstrip('\n') for l in f]
    except:
        sys.stderr.write("[E::stk_subseq] failed to open the input file/stream.\n")
        return 1
    is_bed=False
    for line in bed_lines:
        if not line.strip() or line.startswith('#'): continue
        fields=line.strip().split()
        if len(fields)>=3:
            try:
                int(fields[1]); int(fields[2])
                is_bed=True; break
            except: continue
    rec_dict={name:(name,comment,seq,qual,isfq) for name,comment,seq,qual,isfq in recs}
    if not is_bed:
        for line in bed_lines:
            if not line.strip(): continue
            key=line.strip().split()[0]
            if key in rec_dict:
                rec=rec_dict[key]
                name2,comment2,seq2,qual2,isfq2=rec
                if opt_t:
                    sys.stdout.write(f"{name2}\t{seq2}\n")
                else:
                    if isfq2 and qual2:
                        hdr=name2 + (f" {comment2}" if comment2 else "")
                        sys.stdout.write(f"@{hdr}\n{seq2}\n+\n{qual2}\n")
                    else:
                        hdr=name2 + (f" {comment2}" if comment2 else "")
                        if opt_l and opt_l>0:
                            seqw="\n".join(seq2[i:i+opt_l] for i in range(0,len(seq2),opt_l))
                        else:
                            seqw=seq2
                        sys.stdout.write(f">{hdr}\n{seqw}\n")
        return 0
    else:
        for line in bed_lines:
            if not line.strip() or line.startswith('#'): continue
            fields=line.strip().split()
            if len(fields)<3: continue
            chrom=fields[0]
            try:
                start=int(fields[1]); end=int(fields[2])
            except: continue
            strand='+'
            if len(fields)>=6:
                strand=fields[5]
            elif len(fields)>=4 and fields[3] in ('+','-'):
                strand=fields[3]
            if chrom not in rec_dict:
                continue
            name0,comment0,seq0,qual0,isfq0=rec_dict[chrom]
            sub_seq=seq0[start:end]
            sub_qual=qual0[start:end] if qual0 else None
            if opt_s and strand=='-':
                sub_seq=revcomp(sub_seq)
                if sub_qual: sub_qual=sub_qual[::-1]
            if opt_t:
                sys.stdout.write(f"{chrom}\t{start+1}\t{sub_seq}\n")
            else:
                out_name=f"{chrom}:{start+1}-{end}"
                if isfq0 and qual0:
                    hdr=out_name
                    if opt_l and opt_l>0:
                        sub_seq_w="\n".join(sub_seq[i:i+opt_l] for i in range(0,len(sub_seq),opt_l))
                        sub_qual_w="\n".join(sub_qual[i:i+opt_l] for i in range(0,len(sub_qual),opt_l)) if sub_qual else sub_qual
                    else:
                        sub_seq_w=sub_seq; sub_qual_w=sub_qual
                    sys.stdout.write(f"@{hdr}\n{sub_seq_w}\n+\n{sub_qual_w}\n")
                else:
                    hdr=out_name
                    if opt_l and opt_l>0:
                        sub_seq_w="\n".join(sub_seq[i:i+opt_l] for i in range(0,len(sub_seq),opt_l))
                    else:
                        sub_seq_w=sub_seq
                    sys.stdout.write(f">{hdr}\n{sub_seq_w}\n")
        return 0

def cmd_fqchk(args):
    try:
        opts,rest=getopt.getopt(args,"q:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"fqchk: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    qthres=20
    for o,a in opts:
        if o=='-q':
            try: qthres=int(a)
            except: qthres=20
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk fqchk [-q 20] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_fqchk] failed to open the input file/stream.\n")
        return 1
    fq_recs=[r for r in recs if r[4] and r[3] is not None]
    if not fq_recs:
        sys.stdout.write("min_len: 0; max_len: 0; avg_len: 0.00; 0 distinct quality values\n")
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
        return 0
    lengths=[len(seq) for _,_,seq,_,_ in fq_recs]
    min_len=min(lengths); max_len=max(lengths); avg_len=sum(lengths)/len(lengths)
    all_quals=set()
    for _,_,seq,qual,_ in fq_recs:
        for ch in qual:
            all_quals.add(ord(ch))
    distinct=len(all_quals)
    sys.stdout.write(f"min_len: {min_len}; max_len: {max_len}; avg_len: {avg_len:.2f}; {distinct} distinct quality values\n")
    if qthres==0:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%Q0\t%Q40\n")
    else:
        sys.stdout.write("POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ\t%low\t%high\n")
    max_pos=max_len
    total_bases=sum(lengths)
    total_A=total_C=total_G=total_T=total_N=0
    total_qual=0; total_err=0; low_total=0; high_total=0
    pos_stats=[]
    for p in range(max_len):
        cntA=cntC=cntG=cntT=cntN=0
        qual_sum=0; err_sum=0; low=0; high=0; bese=0
        for name,comment,seq,qual,isfq in fq_recs:
            if p < len(seq):
                base=seq[p].upper()
                if base=='A': cntA+=1
                elif base=='C': cntC+=1
                elif base=='G': cntG+=1
                elif base=='T': cntT+=1
                elif base=='N': cntN+=1
                q=ord(qual[p]) -33 if p < len(qual) else 0
                qual_sum+=q
                # err probability
                err = 10**(-q/10) if q>=0 else 1
                err_sum+=err
                bese+=1
                if q < qthres:
                    low+=1
                else:
                    high+=1
        total_A+=cntA; total_C+=cntC; total_G+=cntG; total_T+=cntT; total_N+=cntN
        total_qual+=qual_sum; total_err+=err_sum; low_total+=low; high_total+=high
        if bese==0: continue
        pctA=cntA/bese*100; pctC=cntC/bese*100; pctG=cntG/bese*100; pctT=cntT/bese*100; pctN=cntN/bese*100
        avgQ=qual_sum/bese if bese else 0
        # errQ as average error Q: -10*log10(avg_err)
        avg_err=err_sum/bese if bese else 0
        if avg_err>0:
            errQ = -10*math.log10(avg_err)
        else:
            errQ=0
        # For qthres==0, last two cols are counts for Q0 vs Q40 etc: low/high still but with different formatting
        perc_low=low/bese*100
        perc_high=high/bese*100
        pos_stats.append((p+1,bese,pctA,pctC,pctG,pctT,pctN,avgQ,errQ,perc_low,perc_high))
    if total_bases>0:
        pctA=total_A/total_bases*100; pctC=total_C/total_bases*100; pctG=total_G/total_bases*100; pctT=total_T/total_bases*100; pctN=total_N/total_bases*100
        avgQ=total_qual/total_bases
        avg_err=total_err/total_bases if total_bases else 0
        if avg_err>0:
            errQ = -10*math.log10(avg_err)
        else:
            errQ=0
        perc_low_total=low_total/total_bases*100
        perc_high_total=high_total/total_bases*100
        sys.stdout.write(f"ALL\t{total_bases}\t{pctA:.1f}\t{pctC:.1f}\t{pctG:.1f}\t{pctT:.1f}\t{pctN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{perc_low_total:.1f}\t{perc_high_total:.1f}\n")
        for p,bese,pA,pC,pG,pT,pN,avgQ,errQ,pl,ph in pos_stats:
            if qthres==0:
                sys.stdout.write(f"{p}\t{bese}\t{pA:.1f}\t{pC:.1f}\t{pG:.1f}\t{pT:.1f}\t{pN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{pl:.2f}\t{ph:.2f}\n")
            else:
                sys.stdout.write(f"{p}\t{bese}\t{pA:.1f}\t{pC:.1f}\t{pG:.1f}\t{pT:.1f}\t{pN:.1f}\t{avgQ:.1f}\t{errQ:.1f}\t{pl:.1f}\t{ph:.1f}\n")
    return 0

def cmd_mergepe(args):
