def cmd_split(args):
    try:
        opts,rest=getopt.getopt(args,"n:l:")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"split: invalid option -- '{bad}'\n")
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    n_files=10; line_len=0
    for o,a in opts:
        if o=='-n':
            try: n_files=int(a)
            except: n_files=10
        elif o=='-l':
            try: line_len=int(a)
            except: line_len=0
    if len(rest)<2:
        sys.stderr.write("Usage: seqtk split [options] <prefix> <in.fa>\nOptions:\n  -n INT    number of files [10]\n  -l INT    line length [0]\n")
        return 1
    prefix=rest[0]; infile=rest[1]
    recs=read_fastx(infile)
    if recs is None:
        sys.stderr.write("[E::stk_split] failed to open the input file/stream.\n")
        return 1
    handles=[]
    for i in range(n_files):
        fname=f"{prefix}.{i+1:05d}.fa"
        d=os.path.dirname(fname)
        if d and not os.path.exists(d):
            os.makedirs(d, exist_ok=True)
        handles.append(open(fname,'w'))
    for idx,rec in enumerate(recs):
        name,comment,seq,qual,isfq=rec
        hdr=name + (f" {comment}" if comment else "")
        fid=idx % n_files
        h=handles[fid]
        if isfq and qual:
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
                qual_w="\n".join(qual[i:i+line_len] for i in range(0,len(qual),line_len))
            else:
                seq_w=seq; qual_w=qual
            h.write(f"@{hdr}\n{seq_w}\n+\n{qual_w}\n")
        else:
            if line_len and line_len>0:
                seq_w="\n".join(seq[i:i+line_len] for i in range(0,len(seq),line_len))
            else:
                seq_w=seq
            h.write(f">{hdr}\n{seq_w}\n")
    for h in handles: h.close()
    return 0

def cmd_trimfq(args):
    try:
        opts,rest=getopt.getopt(args,"q:l:b:e:L:Q")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"trimfq: invalid option -- '{bad}'\n")
        sys.stderr.write("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n\n")
        return 1
    q=0.05; l=30; b=0; e=0; L=0; forceQ=False
    for o,a in opts:
        if o=='-q':
            try: q=float(a)
            except: q=0.05
        elif o=='-l':
            try: l=int(a)
            except: l=30
        elif o=='-b':
            try: b=int(a)
            except: b=0
        elif o=='-e':
            try: e=int(a)
            except: e=0
        elif o=='-L':
            try: L=int(a)
            except: L=0
        elif o=='-Q': forceQ=True
    if len(rest)<1:
        sys.stderr.write("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_trimfq] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        n=len(seq)
        if qual is None and not forceQ:
            # FASTA
            if b!=0 or e!=0 or L!=0:
                start=b
                end=n - e if e!=0 else n
                if L!=0:
                    if b==0 and e==0:
                        start=0; end=min(n,L)
                    else:
                        end=min(end,start+L)
                seq2=seq[start:end]
                sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{seq2}\n")
            else:
                sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{seq}\n")
            continue
        # FASTQ
        if qual is None:
            qual='#'*len(seq)
        if b!=0 or e!=0 or L!=0:
            start=b
            end=n - e if e!=0 else n
            if L!=0:
                if b==0 and e==0:
                    start=0; end=min(n,L)
                else:
                    end=min(end,start+L)
            seq2=seq[start:end]
            qual2=qual[start:end]
        else:
            if q<=0:
                q_phred=100
            else:
                try: q_phred=-10*math.log10(q)
                except: q_phred=20
            left=0; right=n
            while left < right:
                phred=ord(qual[left]) -33
                if phred >= q_phred:
                    break
                left+=1
                if n - left < l: break
            while right > left:
                phred=ord(qual[right-1]) -33
                if phred >= q_phred:
                    break
                right-=1
                if right - left < l: break
            seq2=seq[left:right]
            qual2=qual[left:right]
        hdr=name + (f" {comment}" if comment else "")
        if forceQ or isfq:
            sys.stdout.write(f"@{hdr}\n{seq2}\n+\n{qual2}\n")
        else:
            sys.stdout.write(f">{hdr}\n{seq2}\n")
    return 0

def cmd_hety(args):
    try:
        opts,rest=getopt.getopt(args,"w:t:m")
    except getopt.GetoptError as e:
        sys.stderr.write("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n\n")
        return 1
    w=50000; t=5; m=False
    for o,a in opts:
        if o=='-w':
            try: w=int(a)
            except: w=50000
        elif o=='-t':
            try: t=int(a)
            except: t=5
        elif o=='-m': m=True
    if len(rest)<1:
        sys.stderr.write("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_hety] failed to open the input file/stream.\n")
        return 1
    het_set=set(['R','Y','S','W','K','M','B','D','H','V'])
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        if L <= w:
            windows=[(0,L)]
        else:
            step=w//t if t>0 else w
            if step==0: step=1
            windows=[]
            start=0
            while start < L:
                end=min(start+w, L)
                windows.append((start,end))
                start+=step
        for ws,we in windows:
            sub=seq[ws:we]
            hets=0; eff=0
            for base in sub:
                if m and base.islower(): continue
                eff+=1
                if base.upper() in het_set: hets+=1
            rate=hets/eff*w if eff>0 else 0
            sys.stdout.write(f"{name}\t{ws}\t{we}\t{rate:.2f}\t{eff}\t{hets}\n")
    return 0

def cmd_gc(args):
