        elif o=='-l':
            try: l=int(a)
            except: l=20
        elif o=='-x':
            try: xdrop=float(a)
            except: xdrop=10.0
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk gc [options] <in.fa>\nOptions:\n  -w         identify high-AT regions\n  -f FLOAT   min GC fraction (or AT fraction for -w) [0.60]\n  -l INT     min region length to output [20]\n  -x FLOAT   X-dropoff [10.0]\n")
        return 1
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_gc] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        total_gc=sum(1 for b in seq if b.upper() in ('G','C'))
        total_at=sum(1 for b in seq if b.upper() in ('A','T'))
        total_valid=sum(1 for b in seq if b.upper() in ('A','C','G','T'))
        if total_valid==0: continue
        gc_frac=total_gc/total_valid if total_valid else 0
        at_frac=total_at/total_valid if total_valid else 0
        target=at_frac if highAT else gc_frac
        if target >= f and L >= l:
            sys.stdout.write(f"{name}\t0\t{L}\t{L}\n")
    return 0

def cmd_mutfa(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk mutfa <in.fa> <in.snp>\n\nNote: <in.snp> contains at least four columns per line which are:\n      'chr  1-based-pos  any  base-changed-to'.\n")
        return 1
    fa_path=args[0]; snp_path=args[1]
    recs=read_fastx(fa_path)
    if recs is None:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    snps={}
    try:
        if snp_path.endswith(".gz"):
            open_func=gzip.open; mode='rt'
        else:
            open_func=open; mode='r'
        with open_func(snp_path, mode) as f:
            for line in f:
                if not line.strip() or line.startswith('#'): continue
                fields=line.strip().split()
                if len(fields)<4: continue
                chrom=fields[0]
                try: pos=int(fields[1])
                except: continue
                base=fields[3]
                snps.setdefault(chrom,{})[pos]=base
    except:
        sys.stderr.write("[E::stk_mutfa] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        lst=list(seq)
        if name in snps:
            for pos,base in snps[name].items():
                idx=pos-1
                if 0 <= idx < len(lst):
                    lst[idx]=base.upper() if lst[idx].isupper() else base.lower() if lst[idx].islower() else base
        sys.stdout.write(f">{name + (f' {comment}' if comment else '')}\n{''.join(lst)}\n")
    return 0

def cmd_mergefa(args):
    # manual parse to handle -q with arg
    qthres=0; intersect=False; maskLower=False; random_allele=False; suppress_hets=False
    files=[]
    idx=0
    while idx < len(args):
        if args[idx].startswith('-') and len(args[idx])>1:
            flag=args[idx][1]
            if flag=='q':
                if idx+1 < len(args):
                    try: qthres=int(args[idx+1])
                    except: qthres=0
                    idx+=2; continue
                else: idx+=1; continue
            elif flag=='i': intersect=True
            elif flag=='m': maskLower=True
            elif flag=='r': random_allele=True
            elif flag=='h': suppress_hets=True
            else: pass
        else:
            files.append(args[idx])
        idx+=1
    if len(files)<2:
        sys.stderr.write("\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n\n")
        return 1
    f1=files[-2]; f2=files[-1]
    recs1=read_fastx(f1); recs2=read_fastx(f2)
    if recs1 is None or recs2 is None:
        sys.stderr.write("[E::stk_mergefa] failed to open the input file/stream.\n")
        return 1
    dict2={name:(seq,qual,isfq) for name,comment,seq,qual,isfq in recs2}
    iupac_merge={('A','A'):'A',('C','C'):'C',('G','G'):'G',('T','T'):'T',('A','G'):'R',('G','A'):'R',('C','T'):'Y',('T','C'):'Y',('G','C'):'S',('C','G'):'S',('A','T'):'W',('T','A'):'W',('G','T'):'K',('T','G'):'K',('A','C'):'M',('C','A'):'M',('N','N'):'N'}
    rnd=random.Random(11)
    for name,comment,seq1,qual1,isfq1 in recs1:
        if name not in dict2:
            if intersect: continue
            sys.stdout.write(f">{name}\n{seq1}\n")
            continue
        seq2,qual2,isfq2=dict2[name]
        L=min(len(seq1),len(seq2))
        merged=[]
        same=0; diff=0
        for i in range(L):
            b1=seq1[i].upper(); b2=seq2[i].upper()
            if suppress_hets:
                if b1 in 'RYSWKMBDHV': b1='N'
                if b2 in 'RYSWKMBDHV': b2='N'
            if random_allele:
                het_bases={'R':['A','G'],'Y':['C','T'],'S':['C','G'],'W':['A','T'],'K':['G','T'],'M':['A','C'],'B':['C','G','T'],'D':['A','G','T'],'H':['A','C','T'],'V':['A','C','G']}
                if b1 in het_bases: b1=rnd.choice(het_bases[b1])
                if b2 in het_bases: b2=rnd.choice(het_bases[b2])
            key=(b1,b2)
            if key in iupac_merge: mb=iupac_merge[key]
            elif (b2,b1) in iupac_merge: mb=iupac_merge[(b2,b1)]
            else: mb='N'
            if maskLower and ('N' in (b1,b2)): mb=mb.lower()
            merged.append(mb)
            if b1==b2: same+=1
            else: diff+=1
        sys.stderr.write(f"[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=({same},{diff},0,0,0)\n")
        sys.stdout.write(f">{name}\n{''.join(merged)}\n")
    return 0

def cmd_famask(args):
    if len(args)<2:
        sys.stderr.write("Usage: seqtk famask <src.fa> <mask.fa>\n")
        return 1
    src_path=args[0]; mask_path=args[1]
    recs_src=read_fastx(src_path)
    recs_mask=read_fastx(mask_path)
    if recs_src is None or recs_mask is None:
        sys.stderr.write("[E::stk_famask] failed to open the input file/stream.\n")
        return 1
    mask_dict={name:seq for name,comment,seq,qual,isfq in recs_mask}
    for name,comment,seq,qual,isfq in recs_src:
        mask_seq=mask_dict.get(name)
        if mask_seq is None:
            hdr=name + (f" {comment}" if comment else "")
            sys.stdout.write(f">{hdr}\n{seq}\n")
            continue
        lst=list(seq)
        for i in range(min(len(seq),len(mask_seq))):
            mbase=mask_seq[i]
            if mbase.upper()=='X':
                lst[i]=lst[i].lower()
            elif mbase.islower():
                lst[i]=lst[i].lower()
        hdr=name + (f" {comment}" if comment else "")
        sys.stdout.write(f">{hdr}\n{''.join(lst)}\n")
    return 0

def cmd_dropse(args):
    if len(args)==0:
        recs=read_fastx(None)
        if not recs: return 0
    else:
        recs=read_fastx(args[0])
        if recs is None:
            sys.stderr.write("[E::stk_dropse] failed to open the input file/stream.\n")
            return 1
        if not recs: return 0
    from collections import defaultdict
    groups=defaultdict(list)
    for rec in recs:
        name=rec[0]
        base=name
        if base.endswith("/1") or base.endswith("/2") or base.endswith(".1") or base.endswith(".2"):
            base=base[:-2]
        groups[base].append(rec)
    keep=set()
    for base,lst in groups.items():
        if len(lst)==2:
            names=[r[0] for r in lst]
            suffixes=set()
            for n in names:
                if n.endswith("/1"): suffixes.add("1")
                elif n.endswith("/2"): suffixes.add("2")
                elif n.endswith(".1"): suffixes.add("1")
                elif n.endswith(".2"): suffixes.add("2")
                else: suffixes.add("?")
            if suffixes=={"1","2"}:
                keep.add(base)
            elif len(set(names))==1:
                keep.add(base)
    for rec in recs:
        name=rec[0]
        base=name
        if base.endswith("/1") or base.endswith("/2") or base.endswith(".1") or base.endswith(".2"):
            base=base[:-2]
        if base in keep:
            n,comment,seq,qual,isfq=rec
            hdr=n + (f" {comment}" if comment else "")
            if isfq and qual:
                sys.stdout.write(f"@{hdr}\n{seq}\n+\n{qual}\n")
            else:
                sys.stdout.write(f">{hdr}\n{seq}\n")
    return 0

def cmd_rename(args):
    if len(args)==0:
        recs=read_fastx(None)
        if not recs: return 0
    else:
