    return 0

def cmd_randbase(args):
    if len(args)<1:
        sys.stderr.write("Usage: seqtk randbase <in.fa>\n")
        return 1
    recs=read_fastx(args[0])
    if recs is None:
        sys.stderr.write("[E::stk_randbase] failed to open the input file/stream.\n")
        return 1
    rnd=random.Random(11)
    het_map={'R':['A','G'],'Y':['C','T'],'S':['C','G'],'W':['A','T'],'K':['G','T'],'M':['A','C'],'B':['C','G','T'],'D':['A','G','T'],'H':['A','C','T'],'V':['A','C','G'],'N':['A','C','G','T']}
    for name,comment,seq,qual,isfq in recs:
        new=[]
        for base in seq:
            up=base.upper()
            if up in het_map:
                chosen=rnd.choice(het_map[up])
                if base.islower():
                    chosen=chosen.lower()
                new.append(chosen)
            else:
                new.append(base)
        hdr=name + (f" {comment}" if comment else "")
        sys.stdout.write(f">{hdr}\n{''.join(new)}\n")
    return 0

def cmd_cutN(args):
    try:
        opts,rest=getopt.getopt(args,"n:p:g")
    except getopt.GetoptError as e:
        sys.stderr.write("\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [1000]\n         -p INT    penalty for a non-N [10]\n         -g        print gaps only, no sequence\n\n")
        return 1
    min_n=1000; penalty=10; gaps_only=False
    for o,a in opts:
        if o=='-n':
            try: min_n=int(a)
            except: min_n=1000
        elif o=='-p':
            try: penalty=int(a)
            except: penalty=10
        elif o=='-g': gaps_only=True
    if len(rest)<1:
        sys.stderr.write("\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [1000]\n         -p INT    penalty for a non-N [10]\n         -g        print gaps only, no sequence\n\n")
        return 1
    recs=read_fastx(rest[0])
    if recs is None:
        sys.stderr.write("[E::stk_cutN] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        intervals=[]
        i=0
        while i<L:
            if seq[i].upper()=='N':
                j=i
                while j<L and seq[j].upper()=='N':
                    j+=1
                if j-i >= min_n:
                    intervals.append((i,j))
                i=j
            else:
                i+=1
        if gaps_only:
            for s,e in intervals:
                sys.stdout.write(f"{name}\t{s}\t{e}\n")
            continue
        if not intervals:
            hdr=f"{name}:1-{L}"
            sys.stdout.write(f">{hdr}\n{seq}\n")
        else:
            prev=0
            pieces=[]
            for s,e in intervals:
                if s>prev:
                    pieces.append((prev,s))
                prev=e
            if prev < L:
                pieces.append((prev,L))
            for s,e in pieces:
                if e-s <=0: continue
                sys.stdout.write(f">{name}:{s+1}-{e}\n{seq[s:e]}\n")
    return 0

def cmd_gap(args):
    try:
        opts,rest=getopt.getopt(args,"l:")
    except getopt.GetoptError as e:
        sys.stderr.write("Usage: seqtk gap [-l 50] <in.fa>\n")
        return 1
    min_l=50
    for o,a in opts:
        if o=='-l':
            try: min_l=int(a)
            except: min_l=50
    if len(rest)<1:
        sys.stderr.write("Usage: seqtk gap [-l 50] <in.fa>\n")
        return 1
    recs=read_fastx(rest[0])
    if recs is None:
        sys.stderr.write("[E::stk_gap] failed to open the input file/stream.\n")
        return 1
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        i=0
        while i<L:
            if seq[i].upper()=='N':
                j=i
                while j<L and seq[j].upper()=='N':
                    j+=1
                if j-i >= min_l:
                    sys.stdout.write(f"{name}\t{i}\t{j}\n")
                i=j
            else:
                i+=1
    return 0

def cmd_listhet(args):
