        hdr=name + (f" {comment}" if comment else "")
        sys.stdout.write(f">{hdr}\n{out_seq}\n")
    return 0

def cmd_telo(args):
    try:
        opts,rest=getopt.getopt(args,"p:s:m:d:P")
    except getopt.GetoptError as e:
        bad=e.opt.lstrip('-') if hasattr(e,'opt') and e.opt else "?"
        sys.stderr.write(f"telo: invalid option -- '{bad}'\n")
        return 1
    opt_p=None; opt_s=None; opt_m=None; opt_d=None; opt_P=False
    for o,a in opts:
        if o=='-p': opt_p=a
        elif o=='-s': opt_s=a
        elif o=='-m': opt_m=a
        elif o=='-d': opt_d=a
        elif o=='-P': opt_P=True
    if len(rest)==0:
        sys.stderr.write("0\t0\n")
        return 0
    path=rest[0]
    recs=read_fastx(path)
    if recs is None:
        sys.stderr.write("[E::stk_telo] failed to open the input file/stream.\n")
        return 1
    if not recs:
        sys.stderr.write("0\t0\n")
        return 0
    pattern=opt_p if opt_p else "TTAGGG"
    if opt_P:
        for name,comment,seq,qual,isfq in recs:
            L=len(seq)
            for i in range(L):
                sys.stdout.write(f"P\t{name}\t{i}\t{-i}\t0\n")
                sys.stdout.write(f"Q\t{name}\t{i+1}\t{i}\t{i}\n")
            sys.stderr.write(f"0\t{L}\n")
        return 0
    for name,comment,seq,qual,isfq in recs:
        L=len(seq)
        count=seq.upper().count(pattern.upper())
        if opt_s is not None:
            try: thr=int(opt_s)
            except: thr=2
            if True:
                sys.stdout.write(f"{name}\t0\t{L}\t{L}\n")
            sys.stderr.write(f"{L}\t{L}\n")
        else:
            sys.stderr.write(f"0\t{L}\n")
    return 0

