    if len(sys.argv)<2:
        sys.stderr.write("\nUsage:   seqtk <command> <arguments>\nVersion: 1.5-r133\n\nCommand: seq       common transformation of FASTA/Q\n         size      report the number sequences and bases\n         comp      get the nucleotide composition of FASTA/Q\n         sample    subsample sequences\n         subseq    extract subsequences from FASTA/Q\n         fqchk     fastq QC (base/quality summary)\n         mergepe   interleave two PE FASTA/Q files\n         split     split one file into multiple smaller files\n         trimfq    trim FASTQ using the Phred algorithm\n\n         hety      regional heterozygosity\n         gc        identify high- or low-GC regions\n         mutfa     point mutate FASTA at specified positions\n         mergefa   merge two FASTA/Q files\n         famask    apply a X-coded FASTA to a source FASTA\n         dropse    drop unpaired from interleaved PE FASTA/Q\n         rename    rename sequence names\n         randbase  choose a random base from hets\n         cutN      cut sequence at long N\n         gap       get the gap locations\n         listhet   extract the position of each het\n         hpc       homopolyer-compressed sequence\n         telo      identify telomere repeats in asm or long reads\n\n")
        sys.exit(1)
    cmd=sys.argv[1]
    args=sys.argv[2:]
    if cmd=="seq": sys.exit(cmd_seq(args))
    elif cmd=="size": sys.exit(cmd_size(args))
    elif cmd=="comp": sys.exit(cmd_comp(args))
    elif cmd=="sample": sys.exit(cmd_sample(args))
    elif cmd=="subseq": sys.exit(cmd_subseq(args))
